public class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        Integer currentYear = DateTime.now().year();
        Date yearStart = Date.newInstance(currentYear, 1, 1);
        Date yearEnd   = Date.newInstance(currentYear + 1, 1, 1).addDays(-1);

        List<AggregateResult> results = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE IsWon = true
              AND CloseDate >= :yearStart
              AND CloseDate <= :yearEnd
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ];

        // Pre-populate every requested Id with 0 so the map is complete
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        // Overwrite with actual sums from the aggregate
        for (AggregateResult ar : results) {
            Id accountId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('totalAmount');
            result.put(accountId, total == null ? 0 : total);
        }

        return result;
    }
}
